# Analyzing the changed pairs more systematically
inputs = ['xaefch', 'gbi', 'hcv', 'hybyvd', 'kvzah']
outputs = ['xaefzhd', 'gbi', 'hczwv', 'hybywvd', 'kwvzah']

# Let's manually identify the differences
changed_pairs = []
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        changed_pairs.append((i, inputs[i], outputs[i]))

print("Changed pairs:")
for idx, s_in, s_out in changed_pairs:
    print(f"  {idx}: '{s_in}' -> '{s_out}'")

    # Let's manually find what changed
    s_in_chars = list(s_in)
    s_out_chars = list(s_out)

    print(f"    Characters: {s_in_chars} -> {s_out_chars}")

    # Find positions where they differ
    for j, (char_in, char_out) in enumerate(zip(s_in_chars, s_out_chars)):
        if char_in != char_out:
            print(f"      Position {j}: '{char_in}' -> '{char_out}'")

    # For strings of different lengths, check remaining chars
    if len(s_in) != len(s_out):
        if len(s_in) > len(s_out):
            print(f"      Extra chars in input: {s_in[len(s_out):]}")
        else:
            print(f"      Extra chars in output: {s_out[len(s_in):]}")
    print()

